134	// RunDashboard launches the interactive worktree dashboard. The dashboard owns
135	// the terminal until the user presses enter (select) or q/esc/ctrl+c (quit).
136	func RunDashboard(cfg DashConfig) (DashResult, error) {
137		m := dashModel{
138			items:               cfg.Initial,
139			gather:              cfg.Gather,
140			close:               cfg.Close,
141			fetchDetail:         cfg.FetchDetail,
142			fetchCommitDetail:   cfg.FetchCommitDetail,
143			rebase:              cfg.Rebase,
144			closes:              map[string]*dashCloseState{},
145			rebases:             map[string]*dashRebaseState{},
146			details:             map[string]*dashDetailCache{},
147			detailLoading:       map[string]bool{},
148			commitDetails:       map[string]*dashCommitDetailCache{},
149			commitDetailLoading: map[string]bool{},
150			lastRefresh:         time.Now(),
151		}
152	
153		final, err := tea.NewProgram(m).Run()
154		if err != nil {
155			return DashResult{}, err
156		}
157	
158		fm := final.(dashModel)
159		if fm.switchTo != "" {
160			return DashResult{SwitchTo: fm.switchTo}, nil
161		}
162		return DashResult{}, nil
163	}
