337	// dispatchDetail returns a Cmd that fetches detail for the focused row.
338	// When force is false, fetches only if the row's detail isn't already cached.
339	// When force is true (refresh tick), fetches regardless — used to keep CI/etc.
340	// up to date while the cursor stays put. Returns nil if no fetch is needed
341	// (no callback, no focus, fetch already in flight).
342	func (m dashModel) dispatchDetail(force bool) tea.Cmd {
343		if m.fetchDetail == nil {
344			return nil
345		}
346		if m.cursor < 0 || m.cursor >= len(m.items) {
347			return nil
348		}
349		it := m.items[m.cursor]
350		if m.detailLoading[it.Path] {
351			return nil
352		}
353		if !force {
354			if _, cached := m.details[it.Path]; cached {
355				return nil
356			}
357		}
358		m.detailLoading[it.Path] = true
359		return fetchDetailCmd(m.fetchDetail, it)
360	}
