362	func (m dashModel) Update(msg tea.Msg) (tea.Model, tea.Cmd) {
363		switch msg := msg.(type) {
364		case tea.WindowSizeMsg:
365			m.width = msg.Width
366			m.height = msg.Height
367			return m, nil
368	
369		case tea.KeyPressMsg:
370			// Confirmation prompts intercept all keys.
371			if m.confirm != confirmNone {
372				return m.handleConfirmKey(msg.String())
373			}
374	
375			// Global keys (work in any focus mode)
376			switch msg.String() {
377			case "ctrl+c", "q":
378				return m, tea.Quit
379			case "R":
380				return m.startRebaseAll()
381			case "tab":
382				return m.toggleFocus()
383			case "esc":
384				// Zoom out one level. Levels (deepest first):
385				//   1. commits focused          → worktrees focused (cursor preserved)
386				//   2. worktrees, on a feature  → worktrees, cursor on the trunk
387				//   3. worktrees, on the trunk  → quit
388				// A few esc presses always exit the app no matter how deep you are.
389				if m.focus == focusCommits {
390					m.focus = focusWorktrees
391					m.commitCursor = 0
392					return m, nil
393				}
394				if m.cursor >= 0 && m.cursor < len(m.items) && !m.items[m.cursor].IsBase {
395					for i, it := range m.items {
396						if it.IsBase {
397							m.cursor = i
398							return m, m.dispatchDetail(false)
399						}
400					}
401				}
402				return m, tea.Quit
403			case "s":
404				// Switch to the highlighted worktree from anywhere — the worktree
405				// cursor (m.cursor) is preserved regardless of focus mode.
406				if m.cursor >= 0 && m.cursor < len(m.items) {
407					m.switchTo = m.items[m.cursor].Path
408					return m, tea.Quit
409				}
410				return m, nil
411			}
412	
413			// Pane-specific keys
414			if m.focus == focusCommits {
415				return m.handleCommitsKey(msg.String())
416			}
417			return m.handleWorktreesKey(msg.String())
418	
419		case tickMsg:
420			if m.refreshing {
421				// Already refreshing — just reschedule the next tick.
422				return m, tickCmd()
423			}
424			m.refreshing = true
425			return m, tea.Batch(refreshCmd(m.gather), tickCmd())
426	
427		case statusTickMsg:
428			// Reschedule only — View() will re-render the "updated Ns ago"
429			// counter using the current time.Since(m.lastRefresh).
430			return m, statusTickCmd()
431	
432		case refreshedMsg:
433			m.refreshing = false
434			if msg.err != nil {
435				m.lastErr = msg.err
436				return m, nil
437			}
438			m.items = msg.items
439			m.lastErr = nil
440			m.lastRefresh = time.Now()
441			if m.cursor >= len(m.items) {
442				m.cursor = max(0, len(m.items)-1)
443			}
444			// Refresh the focused row's detail too, so live state (CI/reviews/new
445			// commits) stays in sync at the same cadence as the main table.
446			return m, m.dispatchDetail(true)
447	
448		case detailLoadedMsg:
449			delete(m.detailLoading, msg.path)
450			m.details[msg.path] = &dashDetailCache{data: msg.data, err: msg.err}
451			// Clamp commit cursor if the refreshed commit list shrunk under our feet.
452			if m.cursor >= 0 && m.cursor < len(m.items) && msg.path == m.items[m.cursor].Path {
453				if n := len(msg.data.Commits); m.commitCursor >= n {
454					m.commitCursor = max(0, n-1)
455				}
456			}
457			// If commits are focused, kick off the commit-detail fetch for the
458			// currently-cursored commit (it may have changed).
459			return m, m.dispatchCommitDetail()
460	
461		case commitDetailLoadedMsg:
462			delete(m.commitDetailLoading, msg.hash)
463			m.commitDetails[msg.hash] = &dashCommitDetailCache{data: msg.data, err: msg.err}
464			return m, nil
465	
466		case dashRebaseDoneMsg:
467			st, ok := m.rebases[msg.path]
468			if !ok {
469				return m, nil
470			}
471			if msg.err != nil {
472				st.phase = "failed"
473				st.errMsg = msg.err.Error()
474				return m, nil
475			}
476			st.phase = "done"
477			st.commits = msg.commits
478			return m, tea.Tick(1500*time.Millisecond, func(time.Time) tea.Msg {
479				return dashRebaseCleanupMsg{path: msg.path}
480			})
481	
482		case dashRebaseCleanupMsg:
483			delete(m.rebases, msg.path)
484			if !m.refreshing {
485				m.refreshing = true
486				return m, refreshCmd(m.gather)
487			}
488			return m, nil
489	
490		case dashCloseDoneMsg:
491			st, ok := m.closes[msg.path]
492			if !ok {
493				return m, nil
494			}
495			if msg.err != nil {
496				st.phase = "failed"
497				st.errMsg = msg.err.Error()
498				return m, nil
499			}
500			st.phase = "done"
501			// Hold the "✓ closed" indicator briefly, then drop it and refresh —
502			// the next gather will remove the row from items.
503			return m, tea.Tick(1500*time.Millisecond, func(time.Time) tea.Msg {
504				return dashCloseCleanupMsg{path: msg.path}
505			})
506	
507		case dashCloseCleanupMsg:
508			delete(m.closes, msg.path)
509			if !m.refreshing {
510				m.refreshing = true
511				return m, refreshCmd(m.gather)
512			}
513			return m, nil
514		}
515	
516		return m, nil
517	}
