519	// handleWorktreesKey processes keys when the worktree list owns focus.
520	// Enter zooms into the commits pane (same as Tab); use `s` to switch
521	// to the highlighted worktree.
522	func (m dashModel) handleWorktreesKey(key string) (tea.Model, tea.Cmd) {
523		switch key {
524		case "up", "k":
525			if m.cursor > 0 {
526				m.cursor--
527				return m, m.dispatchDetail(false)
528			}
529		case "down", "j":
530			if m.cursor < len(m.items)-1 {
531				m.cursor++
532				return m, m.dispatchDetail(false)
533			}
534		case "g", "home":
535			m.cursor = 0
536			return m, m.dispatchDetail(false)
537		case "G", "end":
538			m.cursor = max(0, len(m.items)-1)
539			return m, m.dispatchDetail(false)
540		case "c":
541			return m.startClose()
542		case "r":
543			return m.startRebase()
544		case "enter":
545			// Zoom in: focus the commits pane (no-op if there are no commits yet).
546			return m.toggleFocus()
547		}
548		return m, nil
549	}
