551	// handleCommitsKey processes keys when the commits list owns focus.
552	// j/k navigate within the commits; the third panel below auto-follows the
553	// cursor to show full detail for whichever commit is selected.
554	func (m dashModel) handleCommitsKey(key string) (tea.Model, tea.Cmd) {
555		commits := m.focusedCommits()
556		switch key {
557		case "up", "k":
558			if m.commitCursor > 0 {
559				m.commitCursor--
560				return m, m.dispatchCommitDetail()
561			}
562		case "down", "j":
